import { Component, inject, signal } from '@angular/core';
import { ActivatedRoute } from '@angular/router';

import { OrderApiService } from '../order-api.service';
import { Order } from '../order.model';

@Component({
  selector: 'app-order-view',
  templateUrl: './order-view.html'
})
export class OrderView {
  private route = inject(ActivatedRoute);
  private orderApi = inject(OrderApiService);

  protected readonly order = signal<Order | null>(null);
  protected readonly notFound = signal(false);
  protected readonly loading = signal(true);

  constructor() {
    const id = this.route.snapshot.paramMap.get('id');
    if (!id) {
      this.notFound.set(true);
      this.loading.set(false);
      return;
    }
    this.orderApi.getOrder(id).subscribe({
      next: (order) => {
        this.order.set(order);
        this.loading.set(false);
      },
      error: () => {
        this.notFound.set(true);
        this.loading.set(false);
      }
    });
  }
}
---
@if (loading()) {
  <p>Lädt…</p>
} @else if (notFound()) {
  <p>Bestellung nicht gefunden.</p>
} @else if (order(); as o) {
  <h1>Bestellung {{ o.orderId }}</h1>
  <p>Status: {{ o.status }}</p>
  <ul>
    @for (item of o.items; track item.productId + ':' + item.supplierId) {
      <li>
        {{ item.productName }} ({{ item.supplierName }}) — {{ item.quantity }} ×
        {{ item.unitPrice.toFixed(2).replace('.', ',') }} € =
        {{ item.lineTotal.toFixed(2).replace('.', ',') }} €
      </li>
    }
  </ul>
  <p>Gesamtsumme: {{ o.totalPrice.toFixed(2).replace('.', ',') }} €</p>
}
---
export interface OrderItemLine {
  productId: string;
  productName: string;
  supplierId: string;
  supplierName: string;
  quantity: number;
  unitPrice: number;
  lineTotal: number;
}

export interface Order {
  orderId: string;
  status: string;
  items: OrderItemLine[];
  totalPrice: number;
}

export interface OrderRejectionLine {
  productId: string;
  supplierId: string;
  reason: string;
}

export interface OrderRejection {
  error: string;
  lines: OrderRejectionLine[];
}

